% 單邊拉普拉斯：固定轉換對，不需要 Symbolic Math Toolbox
functionId = 'exponential'; % constant、ramp、exponential 或 sine
a = 2; b = 2; % a 為實數；sine 模式要求 b>0
sigma = 1; omega = 1; % s 的實部與虛部，omega 使用 rad/s
validateattributes(sigma,{'double'},{'scalar','real','finite'});
validateattributes(omega,{'double'},{'scalar','real','finite'});
s = complex(sigma,omega); % 明確建立複數，避免把 j 當成變數
boundary = 0; % constant、ramp、sine 的 ROC 邊界
switch functionId
    case 'constant'
        kernel = @(t) exp(-s*t); % f(t)=1 與核函數相乘
    case 'ramp'
        kernel = @(t) t.*exp(-s*t); % 逐元素乘法
    case 'exponential'
        validateattributes(a,{'double'},{'scalar','real','finite'});
        boundary = -a; % 允許 a 為負，但 ROC 必須重新檢查
        kernel = @(t) exp(-(s+a)*t); % 合併指數，減少溢位
    case 'sine'
        validateattributes(b,{'double'},{'scalar','real','finite','positive'});
        kernel = @(t) sin(b*t).*exp(-s*t);
    otherwise
        error('Laplace:Function','不支援此函數。');
end
if sigma <= boundary
    error('Laplace:ROC','s 不在 ROC，單邊拉普拉斯積分不收斂，不輸出解析延拓值。');
end
switch functionId
    case 'constant', F = 1/s;
    case 'ramp', F = 1/s^2;
    case 'exponential', F = 1/(s+a);
    case 'sine', F = b/(s^2+b^2);
end
if ~isfinite(real(F)) || ~isfinite(imag(F))
    error('Laplace:NonFinite','結果超出數值表示範圍。');
end
Fq = integral(kernel,0,Inf,'AbsTol',1e-10,'RelTol',1e-9); % 獨立數值積分核對
difference = abs(F-Fq); % 比較解析式與數值積分
assert(isfinite(difference) && difference <= 1e-8*max(1,abs(F)));
fprintf('ROC: Re(s) > %.12g\n',boundary);
fprintf('F(s) = %.12g %+.12gj；積分核對誤差 %.3e\n',real(F),imag(F),difference);
% 數值積分只是此輸入的核對，不是任意函數的符號積分工具
